import{createHash}from'node:crypto';import{canonicalizeJcsSafeInteger}from'./permit-issuer.js';
export const P3B_PERMIT_SCHEMA_SHA256='09ea97dc21b22014c99b3f324a6a823356e9018cbe78dbd73ea4244235f7df85';export const P3B_CANONICALIZATION_PROFILE_SHA256='4635995634c05bf60037f83d3fc8746ad4eb01879f561fdc9553ca791116ba06';const component=/^[a-z0-9][a-z0-9._-]{0,62}$/;const hash=b=>createHash('sha256').update(b).digest('hex');
export function deriveTrustAudience(service,environment){if(!component.test(service)||!component.test(environment))throw new Error('Invalid audience component');return service+':'+environment;}
export async function createTrustBundle({keyring,rootSigner,rootKid,service,environment,schemaBytes,canonicalizationProfileBytes,bundleRevision,clock=()=>Date.now(),ttlMs=300000}={}){if(!rootSigner||typeof rootSigner.signBundle!=='function')throw new Error('Offline root signBundle(bytes) interface required');if(!Number.isSafeInteger(bundleRevision)||bundleRevision<1)throw new Error('Positive bundleRevision required');if(!Number.isSafeInteger(ttlMs)||ttlMs<1||ttlMs>300000)throw new Error('TTL must be <=300 seconds');const now=clock();if(!Number.isSafeInteger(now)||now<=0)throw new Error('Invalid clock');if(!schemaBytes||hash(schemaBytes)!==P3B_PERMIT_SCHEMA_SHA256||!canonicalizationProfileBytes||hash(canonicalizationProfileBytes)!==P3B_CANONICALIZATION_PROFILE_SHA256)throw new Error('P3-B schema/canonicalization bytes do not match frozen pins');const trust=await keyring.publicTrust(now);const payload={contractVersion:'1.0',issuer:'core',audience:deriveTrustAudience(service,environment),bundleRevision,issuedAt:new Date(now).toISOString(),expiresAt:new Date(now+ttlMs).toISOString(),schemaSha256:P3B_PERMIT_SCHEMA_SHA256,canonicalizationProfileSha256:P3B_CANONICALIZATION_PROFILE_SHA256,keys:trust.keys,revokedKids:trust.revokedKids};const bytes=Buffer.from(canonicalizeJcsSafeInteger(payload));const result=await rootSigner.signBundle(bytes);if(!result||result.rootKid!==rootKid||!result.signature)throw new Error('Offline root signer identity mismatch');if(typeof keyring.recordBundleIssued==='function')await keyring.recordBundleIssued(bundleRevision,now);return{payload,integrity:{algorithm:'EdDSA',rootKid:result.rootKid,signature:Buffer.from(result.signature).toString('base64url')}};}
